<div class="gamification-admin-head"><h2><?php echo $this->lang('Matches') ?></h2><?php echo $this->button_create('admin/matches/add', (string)$this->lang('Create match')) ?></div><div class="table-responsive"><table class="table"><thead><tr><th><?php echo $this->lang('Match') ?></th><th><?php echo $this->lang('Date') ?></th><th><?php echo $this->lang('Score') ?></th><th><?php echo $this->lang('Status') ?></th><th><?php echo $this->lang('Actions') ?></th></tr></thead><tbody><?php foreach ($matches as $match): ?><tr><td><a href="<?php echo url('admin/matches/edit/'.$match['match_id']) ?>"><?php echo utf8_htmlentities(($match['home_team_title'] ?: $match['home_name']).' - '.($match['away_team_title'] ?: $match['away_name'])) ?></a><?php if ($match['tournament_title']): ?><small><?php echo utf8_htmlentities($match['tournament_title']) ?></small><?php endif ?></td><td><?php echo utf8_htmlentities($match['starts_at'] ?? '') ?></td><td><?php echo $match['score_home'] === NULL ? '-' : (int)$match['score_home'].' - '.(int)$match['score_away'] ?></td><td><?php echo utf8_htmlentities($match['status']) ?></td><td><?php echo $this->button_update('admin/matches/edit/'.$match['match_id']) ?><?php echo $this->button_delete('admin/matches/delete/'.$match['match_id']) ?></td></tr><?php endforeach ?></tbody></table></div>
